window.addEventListener('message', function connect(event) {
  if (event.source !== parent || event.data !== 'browser-auth-input' || event.ports.length !== 1) return;
  window.removeEventListener('message', connect);
  const port = event.ports[0];
  const input = document.querySelector('input');
  const changed = () => port.postMessage({ hasValue: input.value.length > 0 });
  input.oninput = input.onchange = changed;
  input.onkeydown = event => {
    if (event.key === 'Enter' && !event.isComposing) {
      event.preventDefault();
      port.postMessage('submit');
    }
  };
  port.onmessage = ({ data, ports }) => {
    if (data === 'read') {
      ports[0].postMessage(input.reportValidity() ? input.value : null);
      ports[0].close();
    } else if (data === 'clear') {
      input.value = '';
      changed();
    } else if (data?.type === 'configure') {
      input.name = data.attributes.name;
      input.type = data.attributes.type;
      input.placeholder = data.attributes.placeholder;
      input.required = data.attributes.required;
      input.disabled = data.attributes.disabled;
      input.setAttribute('aria-label', data.attributes.placeholder);
      Object.assign(input.style, data.style);
      input.style.setProperty('-webkit-font-smoothing', data.fontSmoothing);
      input.style.setProperty('--placeholder', data.placeholderColor);
      document.documentElement.lang = data.lang;
      document.documentElement.dir = data.dir;
      document.querySelectorAll('link').forEach((link, index) => {
        const href = data.fonts[index];
        if (href && link.getAttribute('href') !== href) link.href = href;
        if (!href) link.removeAttribute('href');
      });
      changed();
    }
  };
});
